// Main Game Engine & Controller
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

let lives = 3;
let battery = 100;
let stage = 1;
let monstersLeft = 5;
let gameRunning = false;
let monsters = [];
let flashlightOn = false;
let torchStream = null;

function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

// Sound & Vibration Setup
function triggerVibration(pattern) {
    if ("vibrate" in navigator) {
        navigator.vibrate(pattern);
    }
}

// Flashlight API Integration
async function toggleFlashlight() {
    try {
        if (!torchStream) {
            const stream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: 'environment' }
            });
            torchStream = stream;
            const track = stream.getVideoTracks()[0];
            await track.applyConstraints({ advanced: [{ torch: true }] });
            flashlightOn = true;
        } else {
            const track = torchStream.getVideoTracks()[0];
            flashlightOn = !flashlightOn;
            await track.applyConstraints({ advanced: [{ torch: flashlightOn }] });
        }
        triggerVibration([100, 50, 100]);
    } catch (err) {
        console.log("Flashlight hardware not available on this device, using digital overlay.", err);
        flashlightOn = !flashlightOn;
        triggerVibration(150);
    }
}

// Legendary Canvas Monster Renderer
class Monster {
    constructor(x, y, type) {
        this.x = x;
        this.y = y;
        this.type = type;
        this.size = 50 + Math.random() * 30;
        this.speed = 1.5 + Math.random() * 2;
        this.hp = type === 'boss' ? 5 : 2;
        this.maxHp = this.hp;
        this.angle = 0;
    }

    update(playerX, playerY) {
        const dx = playerX - this.x;
        const dy = playerY - this.y;
        this.angle = Math.atan2(dy, dx);
        this.x += Math.cos(this.angle) * this.speed;
        this.y += Math.sin(this.angle) * this.speed;
    }

    draw() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);

        // Monster Body (Dark Fiend Concept)
        ctx.fillStyle = '#ff0033';
        ctx.beginPath();
        ctx.arc(0, 0, this.size, 0, Math.PI * 2);
        ctx.fill();

        // Spikes / Horns
        ctx.fillStyle = '#660011';
        for (let i = 0; i < 8; i++) {
            ctx.beginPath();
            ctx.moveTo(Math.cos(i * Math.PI / 4) * this.size, Math.sin(i * Math.PI / 4) * this.size);
            ctx.lineTo(Math.cos(i * Math.PI / 4) * (this.size + 15), Math.sin(i * Math.PI / 4) * (this.size + 15));
            ctx.lineTo(Math.cos((i + 0.5) * Math.PI / 4) * this.size, Math.sin((i + 0.5) * Math.PI / 4) * this.size);
            ctx.fill();
        }

        // Glowing Monster Eyes
        ctx.fillStyle = '#ffff00';
        ctx.beginPath();
        ctx.arc(15, -10, 8, 0, Math.PI * 2);
        ctx.arc(15, 10, 8, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#000000';
        ctx.beginPath();
        ctx.arc(18, -10, 3, 0, Math.PI * 2);
        ctx.arc(18, 10, 3, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
    }
}

// Game Loop
let player = { x: window.innerWidth / 2, y: window.innerHeight / 2 };

function spawnMonsters() {
    monsters = [];
    for (let i = 0; i < monstersLeft; i++) {
        const side = Math.floor(Math.random() * 4);
        let x, y;
        if (side === 0) { x = Math.random() * canvas.width; y = -50; }
        else if (side === 1) { x = canvas.width + 50; y = Math.random() * canvas.height; }
        else if (side === 2) { x = Math.random() * canvas.width; y = canvas.height + 50; }
        else { x = -50; y = Math.random() * canvas.height; }
        monsters.push(new Monster(x, y, i === 0 ? 'boss' : 'standard'));
    }
}

function render() {
    if (!gameRunning) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Player torch lighting effect
    const gradient = ctx.createRadialGradient(player.x, player.y, 30, player.x, player.y, flashlightOn ? 350 : 180);
    gradient.addColorStop(0, 'rgba(255, 255, 200, 0.9)');
    gradient.addColorStop(0.5, 'rgba(255, 150, 50, 0.2)');
    gradient.addColorStop(1, 'rgba(0, 0, 0, 0.95)');

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Update and draw monsters
    monsters.forEach((m, index) => {
        m.update(player.x, player.y);
        m.draw();

        // Collision Check with Player
        const dist = Math.hypot(player.x - m.x, player.y - m.y);
        if (dist < m.size + 20) {
            lives--;
            document.getElementById('lives-count').innerText = lives;
            triggerVibration([300, 100, 300]); // Heavy earthquake/hit vibration effect
            monsters.splice(index, 1);
            document.getElementById('monsters-left').innerText = monsters.length;

            if (lives <= 0) {
                alert('💀 انتهت اللعبة! قتلتك الوحوش!');
                gameRunning = false;
            }
        }
    });

    requestAnimationFrame(render);
}

// Event Listeners
document.getElementById('start-btn').addEventListener('click', () => {
    gameRunning = true;
    spawnMonsters();
    render();
    triggerVibration(200);
});

document.getElementById('flash-btn').addEventListener('click', () => {
    toggleFlashlight();
});

window.addEventListener('mousemove', (e) => {
    player.x = e.clientX;
    player.y = e.clientY;
});

window.addEventListener('touchmove', (e) => {
    if (e.touches.length > 0) {
        player.x = e.touches[0].clientX;
        player.y = e.touches[0].clientY;
    }
});
